-- ============================================================
--  ПОЛЮС-11 — СПРАВКА ЭКИПАЖА (F1) (client) v4.1
--  Новый фирменный стиль P11UI + разделы по системам v4.1.
-- ============================================================

local function ToggleHelp()
    if IsValid(POLUS11.HelpFrame) then POLUS11.HelpFrame:Remove() return end
    local C = P11UI and P11UI.C or {}

    local f = P11UI and P11UI.Frame("СТАНЦИЯ «ПОЛЮС-11» — ПАМЯТКА ЭКИПАЖА",
        "F1 — закрыть · справка обновлена под сборку v4.8.1", 660, 580)
        or vgui.Create("DFrame")
    POLUS11.HelpFrame = f

    local scroll = P11UI.Scroll(f, 12, 64, 636, 504)

    local function H(t) P11UI.Head(scroll, t) end
    local function B(t) P11UI.Body(scroll, t, 600) end

    H("ЧТО ЭТО ЗА РЕЖИМ?")
    B("Станция «Полюс-11», Антарктида, 1982. Гарнизон, НКВД, учёные и персонал — против НЕЧТО: существа, которое съедает человека и идеально копирует его — лицо, голос, имя в чате. Кто-то из присутствующих уже может быть не тем, за кого себя выдаёт. Доверяй только огню и тесту крови.")

    H("С ЧЕГО НАЧАТЬ?")
    B("1) Подойди к NPC-кадровику (смотрит на тебя, поворачивает голову) — E или F4, возьми должность. 2) Делай задачи смены (список слева). 3) Держи генератор живым: солярка, износ, поломки. 4) ДЕЛАЙ СВОЁ ДЕЛО — у каждой должности теперь личные занятия за рубли (см. ниже).")

    H("СМЕННЫЕ ДЕЛА И МИНИИГРЫ (v4.1)", C.science)
    B("Почти у каждой должности появились свои занятия с минииграми «нажми клавишу вовремя» (следи за буквой [R/F/T/G] и сжимающимся кольцом):\n• УЧЁНЫЙ — калибровка анализатора: E по лабораторному столу без колбы (60₽ + очки науки).\n• ТЕХНИК — ТО генератора миниигрой при износе 35+/поломке (100₽, снятие нагара).\n• УБОРЩИК — мешки грязи по станции: E, два шага (35₽).")

    H("ОЧКИ НАУКИ (RP) И ГРАНТ ЦНИИ (v4.1)")
    B("Забор крови (+1 RP), тест (+2), вскрытие (+3), калибровка (+1) — копятся в счётчике 🔬 слева внизу. Каждые 5 RP — автоматический ГРАНТ ЦНИИ: 250₽ и слава в общий чат. Наука на Полюсе теперь кормит.")


    H("РУБЛИ, БАГАЖ И ЛАРЁК (v4.0)")
    B("2000₽ за все задачи смены, 500₽ за доп-задачу терминала, мелкие выплаты за дела. /деньги — баланс. У ЛАРЬКА СНАБЖЕНИЯ (E) — оружие ARC9/EFT, рации, пайки, шприцы. Покупки живут в 🎒 БАГАЖЕ (C-меню), переживают смерть; излишки — в ЛИЧНЫЙ СЕЙФ.")

    H("КТО ЗДЕСЬ КТО? (v3.8–3.9)")
    B("РККА — посты, генералы с !приказ. НКВД — допросы, надзор за тестами, ОСОБИСТ с !розыск. УЧЁНЫЕ — образцы, тесты, вскрытия и гранты; ШПРИЦ ТЕСТА КРОВИ — только у «Учёного». ПЕРСОНАЛ: ГРУЗЧИК — бочки, ТЕХНИК — генераторы, МЕДИК — полевой медкейс (ЛКМ+12 раненому, ПКМ — себя), ПОВАР — кормит, УБОРЩИК — чистит и слышит всё, ИНЖЕНЕР — огнемёт.")

    H("ГЕНЕРАТОР, ХОЛОД И МОРОЗ")
    B("Генератор изнашивается и ломается (перегрев/утечка/стартер/скачки): обычные люди — держат E, техник — играет ТО. CTRL+E — режим РЕЗЕРВ. На морозе теряешь тепло: 2,5 минуты льготы после спавна, дальше грейся у генераторов, в помещениях, горячим пайком.")

    H("ОСОБАЯ ВАКАНСИЯ")
    B("Кадровик иногда вывешивает красную «особую вакансию». Первый нажавший E — тихо становится НОСИТЕЛЕМ. Никто не знает, кто это взял. Так Нечто приходит на станцию.")

    H("ДОКУМЕНТЫ")
    B("Удостоверение с личным кодом на всю смену: ЛКМ — предъявить, ПКМ/R — свои. Нечто под маской покажет украденное имя.")

    H("ДЕЛА: ПОВАР / ГРУЗЧИК / МЕДИК (v4.2)", C.gold)
    B("ПОВАР — полевая кухня (ставит админ): миниигра готовки → горячий паёк греет и лечит, порции несут тебе комиссию. ГРУЗЧИК — заявки из C-меню 📦: напиши что надо — у грузчиков маяк на тебе и пунктир линии пути; быстрее пришёл — больше премия. МЕДИК — полевой медкейс с рождения: ЛКМ по раненому +12 ХП, ПКМ — перевязать себя (+8); медсёстры РККА — тоже с медкейсом.")

    H("ЭВЕНТЫ И ЛАРЁК (v4.2)")
    B("Раз в 15–25 минут на лёд падает ЯЩИК СНАБЖЕНИЯ (оранжевый маяк): вскрытие — держать E 8 сек, добыча в багаж. В ларьке каждый день один товар со скидкой 🔥−40%. Итоги смены подводятся периодически: звания ★ЛУЧШИЙ РАБОТНИК/УЧЁНЫЙ/СТРЕЛОК светятся в TAB и сыплют бонус.")

    H("МУТАЦИИ НЕЧТО (v4.2)")
    B("Нечто теперь — единая профессия: !форма меняет тело, а за жертв (убийства/поглощения) копятся МУТАЦИИ. 3 — Регенерация, 5 — Мясогигант (+60 ХП, сильнее когти), 10 — Арахна: паучья туша, бег +20%, огромные прыжки. Прогресс — на экране твари справа внизу.")

    H("ДОСЬЕ ОСОБОГО ОТДЕЛА (v4.2)")
    B("Особисты и командование ведут ленту досье: тесты крови с результатом, аресты, розыски — и (госбезопасность всё видит) попытки подмены результатов. Открытие: /досье — только для НКВД и командного состава.")

    H("НОВОЕ v4.20.0 «СЛЕД»", C.science)
    B("НАРЯД СУТОК у интенданта (панель над нарядами часа): одно задание на весь день × 3 сложности (Л/Т/С — чем тяжелее, тем больше цель и оплата, до 16 800₽); закрываешь дни подряд — растёт СТРИК, каждый 5-й день стрика — ЗОЛОТОЙ наряд с удвоенной наградой. УЛИКИ: после поглощения на месте остаётся след (красная бирка «УЛИКА») — следователи НКВД собирают клавишей E в планшет (досье: чат !улики); от 2 находок строится ПРОФИЛЬ Нечто: должности жертв, ~рост, окно атак — без имён, допросы решают. АВТО-МЕДАЛИ: сервер сам вручает ● Глазной (50 анализов крови), ♠ Дезинфектор (5000 урона по твари), ◇ Санитар Полюса (10 лечек). ЭКОНОМИКА-СТОКИ: !штраф <ник> <50..5000₽> для особого отдела (казна порядка — !казна), аренда личного сейфа 200₽/сутки (первые сутки бесплатно), ночной тариф ларька +35% (23:00–07:00). ПЕРВЫЙ ДЕНЬ: новичку до 4 часов стажа — план из 5 шагов на плашке справа (награды до 1500₽ и паёк). ОПЕРАЦИИ «РУБЕЖ»: админ объявляет в C-меню «⚔ ОПЕРАЦИИ» — вахты слетают на новобранца, выбираешь СССР или АМЕРИКА (солдат выдаётся сам), бой за случайные точки 30 минут: победителям 5000₽, остальным 1000₽. ФЛАГИ: круг 600 юн, чем больше своих в круге — тем быстрее захват, живой враг в круге — шкала стоит. РЕЙДЫ: командир фракции (E по «■ Терминалу рейда») объявляет рейд — 3 точки прорыва на 10 минут, полоса наверху показывает, чья точка. КЛАДМЕН: у «◆ Связного» закладка за 1000₽ → случайная точка (маяк) → E в зоне → миниигра → +2200₽. F6: 🛡 «Модератор на неделю» за 50 ПФ — испытательный срок, ранг снимается сам через 7 дней.")

    H("ДРЕВО СЛУЖБЫ (v4.21.0 «ДРЕВО»)", C.science)
    B("Профы теперь открывает УРОВЕНЬ СЛУЖБЫ (0–10), а не деньги: опыт падает за дела — закрытый наряд +50, сдача улики +30, груз снабжения +30, анализ крови/арест +25, лечение +20, крафт/приказ +15, кухня/уборка/взятие контракта +10, обыск +5, покупка +3 • C-меню → «⭐ ДРЕВО СЛУЖБЫ»: ветки РККА и УЧЁНЫЕ. У каждого БАЗА (сама по уровню) и 3 ПУТИ: РККА — ШТУРМ / РАЗВЕДКА / МЕДСЛУЖБА, учёные — БИОХИМИЯ / РУКОВОДСТВО / ПОЛЕВОЙ ПРОТОКОЛ (перки: +25% к опыту за науку, стипендия ЦНИИ). Первый открытый узел ВЫБИРАЕТ путь — два других закрываются; идти строго сверху вниз • ОТКАТ ветки — 100 000₽, опыт и уровень СОХРАНЯЮТСЯ (тест других профов). Ранг Staff Leader+ древо не ограничивает.")
    B("АРЕСТ ПО-НОВОМУ (v4.22.0 «ОКОВЫ»): у особого отдела НКВД и командиров РККА (комиссар/генералы) в снаряге — НАРУЧНИКИ. ЛКМ навстречу человеку — защёлкнуть: снаряжение цели изымается, связанный сам ИДЁТ ЗА конвоиром (движение/огонь/юз связаны, суицид/машина/смена профы закрыты, далеко не оторваться — подтянут). ПКМ или R — отпустить: снаряга вернётся. Камеру оформляет НАЧАЛЬНИК КАРАУЛА (ставится из 📍 «Расставить»): подводишь связанного, E — срок 3/5/10 минут или «отпустить». Оформленный арест конвоиру: опыт службы +25, дело в досье, объявление в репродуктор. Стафф в наручники не берём. Опыт за болтовню в рацию и за взятие должности из древа убран — уровень кормят только дела.")

    H("КЛАВИШИ")
    B("F1 — справка • F4 — должности • F2 — 3-е лицо • F3 — свободный курсор • TAB — состав станции · F6 — поддержка станции • C — действия/жесты/багаж • Q — меню инструментов (ранг Developer+) • /р — рация · /канал — волна рации · /шепот·/крик — громкость речи • !работа • !репорт — админам • !ролл • /menu — панель админов.")

    H("ЕСЛИ ТЫ НЕЧТО...")
    B("Не показывайся. Воруй личности, действуй в темноте. R — маскировка, !крик — устрашение, !форма — смена тела. Тест крови и вскрытие тебя выдают.")

    H("ПРАВИЛА СТАНЦИИ")
    B("Не мешай RP. Не палюй стройку. Арест/бан — за дело. Вопросы — администрации (звание в TAB). Сборка готовится к ОТКРЫТОМУ АЛЬФА-ТЕСТУ: нашёл баг — !репорт.")
end

concommand.Add("p11_help", ToggleHelp)

hook.Add("PlayerBindPress", "P11.HelpF1", function(ply, bind, pressed)
    if not pressed then return end
    if bind == "gm_showhelp" then
        ToggleHelp()
        return true
    end
end)
